<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useInsuranceStore } from '../stores/insurance'
import { insuranceApi } from '../api'
import type { InsuranceClaim } from '../types'
import BaseModal from '@/components/common/BaseModal.vue'
import BaseStatusBadge from '@/components/common/BaseStatusBadge.vue'

const store = useInsuranceStore(), search = ref(''), status = ref(''), activeTab = ref('policies'), claims = ref<InsuranceClaim[]>([]), providers = ref(store.providers)
const error = ref(''), success = ref(''), providerModal = ref(false), providerId = ref<number|null>(null), providerForm = ref({name:'',contact_name:'',email:'',phone:'',address:'',notes:''}), claimModal = ref(false)
const claim = ref({ policy_id: 0, incident_date: '', reference_number: '', amount: '', status: 'submitted', notes: '' })
async function load() { error.value = ''; try { await store.load({ search: search.value || undefined, status: status.value || undefined }); providers.value = store.providers; claims.value = await insuranceApi.claims({ per_page: 10 }) } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load insurance data.' } }
function newProvider(){providerId.value=null;providerForm.value={name:'',contact_name:'',email:'',phone:'',address:'',notes:''};providerModal.value=true}
async function editProvider(id:number){try{const p=await insuranceApi.provider(id);providerId.value=p.id;providerForm.value={name:p.name,contact_name:p.contact_name||'',email:p.email||'',phone:p.phone||'',address:p.address||'',notes:p.notes||''};providerModal.value=true}catch(e:any){error.value=e?.response?.data?.message||'Unable to load provider.'}}
async function saveProvider() { try { if(providerId.value) await insuranceApi.updateProvider(providerId.value,providerForm.value);else await insuranceApi.createProvider(providerForm.value); providerModal.value = false; success.value = providerId.value?'Provider updated.':'Provider created.'; await load() } catch (e: any) { error.value = e?.response?.data?.message || 'Unable to save provider.' } }
async function deleteProvider(id:number,name:string,count:number){if(count>0){error.value='This provider has policies and cannot be deleted.';return}if(!window.confirm(`Delete provider ${name}?`))return;try{await insuranceApi.deleteProvider(id);success.value='Provider deleted.';await load()}catch(e:any){error.value=e?.response?.data?.message||'Unable to delete provider.'}}
async function createClaim() { try { await insuranceApi.createClaim(claim.value); claimModal.value = false; success.value = 'Claim created and its status recorded.'; await load() } catch (e: any) { error.value = e?.response?.data?.message || 'Unable to create claim.' } }
onMounted(load)
</script>
<template>
  <main class="fleet-module page-content">
    <div class="page-heading"><div class="fleet-intro"><span class="fleet-intro-icon"><i class="bi bi-shield-check" aria-hidden="true"/></span><div><h2>Fleet coverage</h2><p>Keep policies, claims and insurance providers in one place.</p></div></div><div class="d-flex gap-2"><button class="btn btn-outline-primary" @click="newProvider"><i class="bi bi-building-add me-1"/> Add provider</button><RouterLink to="/insurance/create" class="btn btn-primary"><i class="bi bi-plus-lg me-1"/> New policy</RouterLink></div></div>
    <div v-if="error" class="alert alert-danger" role="alert">{{ error }}</div><div v-if="success" class="alert alert-success" role="status">{{ success }}<button class="btn-close float-end" aria-label="Dismiss" @click="success = ''"/></div>
    <div v-if="store.loading" class="alert alert-light border">Loading insurance recordsâ€¦</div>
    <template v-else-if="store.dashboard">
      <div class="row g-3 mb-4"><div v-for="item in [{label:'Total policies',value:store.dashboard.total_policies,icon:'bi-shield-check'},{label:'Active',value:store.dashboard.active_policies,icon:'bi-check-circle'},{label:'Expiring soon',value:store.dashboard.expiring_soon_policies,icon:'bi-alarm'},{label:'Open claims',value:store.dashboard.claims.open,icon:'bi-clipboard2-pulse'}]" :key="item.label" class="col-6 col-xl-3"><div class="card h-100 shadow-sm"><div class="card-body d-flex align-items-center justify-content-between"><div><div class="text-muted small">{{ item.label }}</div><div class="fs-3 fw-semibold">{{ item.value }}</div></div><i class="bi fs-2 text-primary" :class="item.icon"/></div></div></div></div>
      <div class="fleet-tabs d-flex gap-2 mb-3"><button v-for="tab in [{id:'policies',label:'Policies'},{id:'claims',label:'Claims'},{id:'providers',label:'Providers'}]" :key="tab.id" class="btn" :aria-pressed="activeTab===tab.id" :class="activeTab===tab.id?'btn-primary':'btn-outline-secondary border-0'" @click="activeTab=tab.id">{{ tab.label }}</button></div>
      <section v-if="activeTab==='policies'" class="card shadow-sm"><div class="card-header bg-white d-flex flex-wrap gap-2 justify-content-between"><h2 class="h5 mb-0 align-self-center">Policies</h2><div class="d-flex gap-2"><input v-model="search" class="form-control" placeholder="Search policy or provider" aria-label="Search policies" @keyup.enter="load"><select v-model="status" class="form-select" aria-label="Filter by status" @change="load"><option value="">All statuses</option><option v-for="s in ['active','expiring','expired','scheduled','cancelled','archived']" :key="s" :value="s">{{ s }}</option></select><button class="btn btn-outline-primary" @click="load">Search</button></div></div>
        <div v-if="store.policies.length" class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Policy</th><th>Fleet vehicle</th><th>Provider</th><th>Coverage dates</th><th>Premium</th><th>Status</th><th><span class="visually-hidden">Actions</span></th></tr></thead><tbody><tr v-for="p in store.policies" :key="p.id"><td><RouterLink :to="`/insurance/${p.id}`" class="fw-semibold">{{ p.policy_number }}</RouterLink><div class="text-muted small text-capitalize">{{ p.insurance_type }}</div></td><td>{{ p.vehicle?.plate_no || 'â€”' }}<div class="text-muted small text-capitalize">{{ p.vehicle?.fleet }} fleet</div></td><td>{{ p.provider?.name || 'â€”' }}</td><td>{{ p.start_date }}<div class="text-muted small">to {{ p.expiration_date }}</div></td><td>{{ p.currency }} {{ p.premium_amount }}</td><td><BaseStatusBadge :status="p.status"/></td><td><RouterLink :to="`/insurance/${p.id}`" class="btn btn-sm btn-outline-secondary" :aria-label="`View policy ${p.policy_number}`">View</RouterLink></td></tr></tbody></table></div><div v-else class="p-4 text-center text-muted">No insurance policies match these filters.</div>
      </section>
      <section v-else-if="activeTab==='claims'" class="card shadow-sm"><div class="card-header bg-white d-flex justify-content-between"><h2 class="h5 mb-0">Recent claims</h2><button class="btn btn-sm btn-primary" :disabled="!store.policies.length" @click="claim.policy_id=store.policies[0]?.id || 0; claimModal=true">New claim</button></div><div v-if="claims.length" class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Reference</th><th>Policy</th><th>Incident</th><th>Amount</th><th>Status</th><th/></tr></thead><tbody><tr v-for="c in claims" :key="c.id"><td>{{ c.reference_number }}</td><td>{{ c.policy?.policy_number || c.policy_id }}</td><td>{{ c.incident_date }}</td><td>{{ c.policy?.currency }} {{ c.amount }}</td><td><BaseStatusBadge :status="c.status"/></td><td><RouterLink :to="`/insurance/${c.policy_id}`" class="btn btn-sm btn-outline-secondary">View policy</RouterLink></td></tr></tbody></table></div><div v-else class="p-4 text-center text-muted">No claims have been recorded.</div></section>
      <section v-else class="card shadow-sm"><div class="card-header bg-white d-flex justify-content-between"><h2 class="h5 mb-0">Insurance providers</h2><button class="btn btn-sm btn-primary" @click="newProvider">Add provider</button></div><div v-if="providers.length" class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Provider</th><th>Contact</th><th>Phone</th><th>Policies</th><th>Actions</th></tr></thead><tbody><tr v-for="p in providers" :key="p.id"><td class="fw-semibold">{{ p.name }}</td><td>{{ p.contact_name || p.email || 'â€”' }}</td><td>{{ p.phone || 'â€”' }}</td><td>{{ p.policies_count ?? 'â€”' }}</td><td><div class="d-flex gap-1"><button class="btn btn-sm btn-outline-primary" @click="editProvider(p.id)">Details / Edit</button><button class="btn btn-sm btn-outline-danger" :disabled="(p.policies_count||0)>0" @click="deleteProvider(p.id,p.name,p.policies_count||0)">Delete</button></div></td></tr></tbody></table></div><div v-else class="p-4 text-center text-muted">No providers yet.</div></section>
    </template>
    <div v-else class="alert alert-light border">Insurance dashboard is not available.</div>
    <BaseModal :open="providerModal" :title="providerId?'Insurance provider details':'Add insurance provider'" @close="providerModal=false"><div class="row g-3"><div class="col-12"><label class="form-label" for="provider-name">Provider name</label><input id="provider-name" v-model="providerForm.name" class="form-control" maxlength="255" required></div><div class="col-md-6"><label class="form-label" for="provider-contact">Contact name</label><input id="provider-contact" v-model="providerForm.contact_name" class="form-control"></div><div class="col-md-6"><label class="form-label" for="provider-phone">Phone</label><input id="provider-phone" v-model="providerForm.phone" class="form-control"></div><div class="col-12"><label class="form-label" for="provider-email">Email</label><input id="provider-email" v-model="providerForm.email" class="form-control" type="email"></div><div class="col-12"><label class="form-label" for="provider-address">Address</label><textarea id="provider-address" v-model="providerForm.address" class="form-control" rows="2"/></div><div class="col-12"><label class="form-label" for="provider-notes">Notes</label><textarea id="provider-notes" v-model="providerForm.notes" class="form-control" rows="2"/></div></div><template #actions><button class="btn btn-outline-secondary" @click="providerModal=false">Cancel</button><button class="btn btn-primary" :disabled="!providerForm.name.trim()" @click="saveProvider">Save provider</button></template></BaseModal>
    <BaseModal :open="claimModal" title="Create insurance claim" @close="claimModal=false"><div class="row g-3"><div class="col-12"><label class="form-label" for="claim-policy">Policy</label><select id="claim-policy" v-model.number="claim.policy_id" class="form-select"><option v-for="p in store.policies" :key="p.id" :value="p.id">{{ p.policy_number }} Â· {{ p.vehicle?.plate_no }}</option></select></div><div class="col-md-6"><label class="form-label" for="claim-ref">Reference</label><input id="claim-ref" v-model="claim.reference_number" class="form-control" required></div><div class="col-md-6"><label class="form-label" for="claim-date">Incident date</label><input id="claim-date" v-model="claim.incident_date" class="form-control" type="date" required></div><div class="col-md-6"><label class="form-label" for="claim-amount">Amount</label><input id="claim-amount" v-model="claim.amount" class="form-control" inputmode="decimal" required></div><div class="col-md-6"><label class="form-label" for="claim-status">Status</label><select id="claim-status" v-model="claim.status" class="form-select"><option v-for="s in ['submitted','under_review','approved','rejected','paid','closed']" :key="s">{{ s }}</option></select></div><div class="col-12"><label class="form-label" for="claim-notes">Notes</label><textarea id="claim-notes" v-model="claim.notes" class="form-control"/></div></div><template #actions><button class="btn btn-outline-secondary" @click="claimModal=false">Cancel</button><button class="btn btn-primary" @click="createClaim">Save claim</button></template></BaseModal>
  </main>
</template>
